import React, { useState, useEffect } from "react";
import { motion } from "framer-motion";

/* ===================== NAVBAR ===================== */
const Navbar = ({ activeSection, toggleDarkMode, darkMode }) => {
  const sections = ["about", "skills", "experience", "projects", "contact"];

  return (
    <nav className="fixed w-full z-50 bg-white dark:bg-gray-900 shadow">
      <div className="max-w-6xl mx-auto px-6 py-4 flex justify-between items-center">
        <div className="text-2xl font-bold text-primary">Muhammed Fazal</div>

        <div className="hidden md:flex space-x-6 items-center">
          {sections.map((section) => (
            <a
              key={section}
              href={`#${section}`}
              className={`hover:text-primary transition ${
                activeSection === section
                  ? "text-primary font-semibold"
                  : "text-gray-700 dark:text-gray-300"
              }`}
            >
              {section.charAt(0).toUpperCase() + section.slice(1)}
            </a>
          ))}

          <button
            onClick={toggleDarkMode}
            className="ml-4 px-3 py-1 rounded bg-gray-200 dark:bg-gray-700 text-gray-900 dark:text-white"
          >
            {darkMode ? "Light" : "Dark"}
          </button>
        </div>
      </div>
    </nav>
  );
};

/* ===================== HERO ===================== */
const Hero = () => (
  <section
    id="home"
    className="relative h-screen flex items-center justify-center text-center overflow-hidden
               bg-gradient-to-br from-primary to-secondary text-white"
  >
    <motion.div
      initial={{ opacity: 0, y: 40 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 1 }}
      className="z-10 px-6"
    >
      <h1 className="text-5xl md:text-6xl font-bold mb-6">
        Muhammed Fazal
      </h1>
      <p className="text-xl md:text-2xl max-w-3xl mx-auto mb-8">
        Backend-focused Full Stack Developer with 6+ years building scalable
        systems using Laravel, Node.js, React & Cloud platforms.
      </p>
      <a
        href="#contact"
        className="inline-block px-8 py-3 bg-white text-primary font-semibold rounded-lg hover:bg-gray-100 transition"
      >
        Contact Me
      </a>
    </motion.div>
  </section>
);

/* ===================== ABOUT ===================== */
const About = () => (
  <section id="about" className="py-20 bg-gray-50 dark:bg-gray-800">
    <div className="max-w-4xl mx-auto px-6">
      <h2 className="text-4xl font-bold text-primary mb-8 text-center">
        About Me
      </h2>

      <p className="text-lg text-gray-700 dark:text-gray-300 mb-4">
        Backend-focused Full Stack Developer with 6+ years of experience
        building scalable enterprise applications using Laravel, PHP, Node.js,
        React, Vue.js and React Native.
      </p>

      <p className="text-lg text-gray-700 dark:text-gray-300 mb-4">
        Strong expertise in REST APIs, microservices, database optimization,
        queue systems, CI/CD pipelines and cloud deployments across AWS, GCP
        and Azure.
      </p>

      <p className="text-lg text-gray-700 dark:text-gray-300">
        📍 Sweden &nbsp;|&nbsp; 📞 +46 764502891 &nbsp;|&nbsp;
        ✉️ muhammedfazalkv@gmail.com
      </p>
    </div>
  </section>
);

/* ===================== SKILLS ===================== */
const Skills = () => {
  const skills = [
    "Laravel", "PHP 8+", "Node.js", "React", "Vue.js", "React Native",
    "TypeScript", "JavaScript", "MySQL", "PostgreSQL", "MongoDB",
    "AWS", "Azure", "Docker", "Redis", "CI/CD", "SOLID", "DDD"
  ];

  return (
    <section id="skills" className="py-20 bg-white dark:bg-gray-900">
      <div className="max-w-6xl mx-auto px-6 text-center">
        <h2 className="text-4xl font-bold text-primary mb-12">
          Technical Skills
        </h2>

        <div className="flex flex-wrap justify-center gap-4">
          {skills.map((skill) => (
            <span
              key={skill}
